@namespace sv_05eae0f8889647f2bca115591786c69b.Components.JobApplication

<h5 class="mb-3">Work History</h5>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryEditor Entry="@Entries[index]"
                     Index="index"
                     CanRemove="@(Entries.Count > 1)"
                     OnChanged="entry => UpdateEntry(index, entry)"
                     OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
        {
            Entries = [new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty)];
        }
        else
        {
            Entries = new List<WorkEntry>(Entries);
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private void UpdateEntry(int index, WorkEntry updated) => Entries[index] = updated;

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

