@code {
    [Parameter] public List<Reference> References { get; set; } = [];
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References =
            [
                new Reference(string.Empty, string.Empty, string.Empty, string.Empty),
                new Reference(string.Empty, string.Empty, string.Empty, string.Empty)
            ];
        }
        else
        {
            References = new List<Reference>(References);
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void UpdateReference(int index, Reference updated) => References[index] = updated;

    private void RemoveReference(int index) => References.RemoveAt(index);

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
