+        }
+    }
+
+    private void UpdateReference(int index, Reference updated) => References[index] = updated;
+
+    private void RemoveReference(int index) => References.RemoveAt(index);
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = null;
+
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
+            {
+                ErrorMessage = "Each reference requires at least a name and email.";
+                return;
+            }
+        }
+
+        await OnNext.InvokeAsync(References);
+    }
+}
