@namespace sv_05eae0f8889647f2bca115591786c69b.Components.JobApplication

<h5 class="mb-3">Cover Letter</h5>

<div class="mb-2">
    <textarea class="form-control" rows="10" @oninput="OnInput" value="@CoverLetter"></textarea>
</div>
<div class="text-muted text-end mb-3">
    <small>@CoverLetter.Length / @MaxCharacters characters</small>
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxCharacters = 2000;
    private string? ErrorMessage;

    private void OnInput(ChangeEventArgs e)
    {
        var text = (string?)e.Value ?? string.Empty;
        CoverLetter = text.Length > MaxCharacters ? text[..MaxCharacters] : text;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
}

